import 'dart:convert';
import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter/material.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
import '../database/database_helper.dart';

// ════════════════════════════════════════════════════════════════════════════
//  pdf_service.dart — DISPERSALUD IA
//  Genera reportes PDF con logos institucionales y DISPERSALUD IA
//  Logos embebidos en Base64 → no requieren assets en tiempo de ejecución
// ════════════════════════════════════════════════════════════════════════════

// ── Colores DISPERSALUD ───────────────────────────────────────────────────
const _verde     = PdfColor.fromInt(0xFF1D9E75);
const _verdeOsc  = PdfColor.fromInt(0xFF0F6E52);
const _oscuro    = PdfColor.fromInt(0xFF111111);
const _texto     = PdfColor.fromInt(0xFF1A1A1A);
const _gris      = PdfColor.fromInt(0xFF2A2A2A);
const _grisClaro = PdfColor.fromInt(0xFFF5F5F5);
const _borde     = PdfColor.fromInt(0xFFE0E0E0);

// ── Logos embebidos Base64 ────────────────────────────────────────────────
// Colombia Potencia/Salud/INS/SIVIGILA — strip horizontal 635×69px
const _kLogosInstitucionales = '';

// Logo DISPERSALUD IA — cuadrado 200×200px
const _kLogoDispersalud = '';

// ── Alertas SIVIGILA activas ──────────────────────────────────────────────
const List<Map<String, dynamic>> _kAlertasActivas = [
  {
    'codigo': 'DEN', 'nombre': 'Dengue',
    'municipio': 'Santander de Quilichao',
    'nivel': 'urgente', 'casos': 18,
    'mensaje': 'Incremento de casos en ultimas 2 semanas. Se activa alerta epidemiologica.',
  },
  {
    'codigo': 'MAL', 'nombre': 'Malaria',
    'municipio': 'Lopez de Micay',
    'nivel': 'alerta', 'casos': 5,
    'mensaje': 'Casos confirmados de P. falciparum. Reforzar busqueda activa con gota gruesa.',
  },
  {
    'codigo': 'DES', 'nombre': 'Desnutricion Aguda',
    'municipio': 'Toribio',
    'nivel': 'alerta', 'casos': 3,
    'mensaje': 'Tres ninos menores de 2 anos con desnutricion aguda severa. Activar ICBF.',
  },
];

class PdfService {
  // ── Caché de imágenes decodificadas ──────────────────────────────────────
  static pw.MemoryImage? _imgLogos;
  static pw.MemoryImage? _imgDispersalud;

  static void _cargarImagenes() {
    _imgLogos      ??= pw.MemoryImage(base64Decode(_kLogosInstitucionales));
    _imgDispersalud ??= pw.MemoryImage(base64Decode(_kLogoDispersalud));
  }

  // ════════════════════════════════════════════════════════════════════════
  // MÉTODO PRINCIPAL
  // ════════════════════════════════════════════════════════════════════════
  static Future<void> generarYCompartir({
    required BuildContext context,
    required int pacienteId,
    required String pacienteNombre,
  }) async {
    // 1 — Cargar datos
    final paciente  = await DatabaseHelper.instance.obtenerPaciente(pacienteId);
    final consultas = await DatabaseHelper.instance.consultasDePaciente(pacienteId);
    final alertas   = await DatabaseHelper.instance.obtenerAlertas();

    // 2 — Decodificar imágenes
    _cargarImagenes();

    // 3 — Construir PDF
    final pdf = pw.Document(
      title: 'Historial clinico — $pacienteNombre',
      author: 'DISPERSALUD IA',
    );

    pdf.addPage(
      pw.MultiPage(
        pageFormat: PdfPageFormat.a4,
        margin: const pw.EdgeInsets.fromLTRB(28, 28, 28, 32),
        header: (ctx) => _header(pacienteNombre, ctx),
        footer: (ctx) => _footer(ctx),
        build: (ctx) => [
          _seccionPaciente(paciente),
          pw.SizedBox(height: 18),
          _seccionConsultas(consultas),
          pw.SizedBox(height: 18),
          _seccionAlertas(alertas),
          pw.SizedBox(height: 18),
          _pieLegal(),
        ],
      ),
    );

    // 4 — Compartir / imprimir
    final pdfBytes = await pdf.save();
    if (kIsWeb) {
      await Printing.layoutPdf(
        onLayout: (_) async => pdfBytes,
        name: 'DISPERSALUD_Informe.pdf',
      );
    } else {
      await Printing.sharePdf(
        bytes: pdfBytes,
        filename:
            'DISPERSALUD_${pacienteNombre.replaceAll(' ', '_')}_${DateTime.now().millisecondsSinceEpoch}.pdf',
      );
    }
  }

  // ════════════════════════════════════════════════════════════════════════
  // HEADER — aparece en CADA página
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _header(String nombre, pw.Context ctx) {
    final esPortada = ctx.pageNumber == 1;

    return pw.Column(children: [
      // ── Banda superior: logos institucionales ──────────────────────────
      pw.Container(
        padding: const pw.EdgeInsets.symmetric(vertical: 8, horizontal: 4),
        decoration: const pw.BoxDecoration(
          color: PdfColors.white,
          border: pw.Border(
            bottom: pw.BorderSide(color: _borde, width: 0.5),
          ),
        ),
        child: pw.Row(
          mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
          crossAxisAlignment: pw.CrossAxisAlignment.center,
          children: [
            // Logos: Colombia, MinSalud, INS, SIVIGILA
            pw.Image(
              _imgLogos!,
              width: 220,
              height: 24,
              fit: pw.BoxFit.contain,
            ),
            // Logo DISPERSALUD IA + nombre
            pw.Row(
              crossAxisAlignment: pw.CrossAxisAlignment.center,
              children: [
                pw.Image(
                  _imgDispersalud!,
                  width: 28,
                  height: 28,
                  fit: pw.BoxFit.contain,
                ),
                pw.SizedBox(width: 6),
                pw.Column(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  children: [
                    pw.Text('DISPERSALUD IA',
                        style: pw.TextStyle(
                            fontSize: 11,
                            fontWeight: pw.FontWeight.bold,
                            color: _verde)),
                    pw.Text('Sistema de Salud Rural · Cauca',
                        style: pw.TextStyle(
                            fontSize: 7, color: PdfColors.grey600)),
                  ],
                ),
              ],
            ),
          ],
        ),
      ),

      // ── Segunda fila: título del reporte + paciente ────────────────────
      pw.Container(
        padding: const pw.EdgeInsets.fromLTRB(4, 8, 4, 10),
        decoration: const pw.BoxDecoration(
          border: pw.Border(
            bottom: pw.BorderSide(color: _verde, width: 2),
          ),
        ),
        child: pw.Row(
          mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
          children: [
            pw.Column(
              crossAxisAlignment: pw.CrossAxisAlignment.start,
              children: [
                pw.Text(
                  esPortada ? 'Historial Clinico Integral' : 'Historial Clinico Integral (cont.)',
                  style: pw.TextStyle(
                      fontSize: 13,
                      fontWeight: pw.FontWeight.bold,
                      color: _texto),
                ),
                pw.SizedBox(height: 2),
                pw.Text(
                  'Promotor de salud rural — Resguardos indigenas del Cauca',
                  style: pw.TextStyle(fontSize: 8, color: PdfColors.grey600),
                ),
              ],
            ),
            pw.Column(
              crossAxisAlignment: pw.CrossAxisAlignment.end,
              children: [
                pw.Text('Paciente',
                    style: pw.TextStyle(
                        fontSize: 8, color: PdfColors.grey500)),
                pw.Text(nombre,
                    style: pw.TextStyle(
                        fontSize: 10,
                        fontWeight: pw.FontWeight.bold,
                        color: _texto)),
                pw.Text(
                  _fechaHoy(),
                  style: pw.TextStyle(fontSize: 8, color: PdfColors.grey600),
                ),
              ],
            ),
          ],
        ),
      ),

      pw.SizedBox(height: 6),
    ]);
  }

  // ════════════════════════════════════════════════════════════════════════
  // FOOTER
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _footer(pw.Context ctx) {
    return pw.Container(
      padding: const pw.EdgeInsets.only(top: 6),
      decoration: const pw.BoxDecoration(
        border: pw.Border(top: pw.BorderSide(color: _borde, width: 0.5)),
      ),
      child: pw.Row(
        mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
        children: [
          pw.Row(children: [
            pw.Image(_imgDispersalud!, width: 12, height: 12),
            pw.SizedBox(width: 4),
            pw.Text(
              'DISPERSALUD IA  ·  Generado: ${_fechaHoy()}  ·  Ley 1581 datos protegidos',
              style: pw.TextStyle(fontSize: 7, color: PdfColors.grey500),
            ),
          ]),
          pw.Text(
            'Pagina ${ctx.pageNumber} de ${ctx.pagesCount}',
            style: pw.TextStyle(fontSize: 7, color: PdfColors.grey500),
          ),
        ],
      ),
    );
  }

  // ════════════════════════════════════════════════════════════════════════
  // SECCIÓN PACIENTE
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _seccionPaciente(Map<String, dynamic>? p) {
    if (p == null) return pw.SizedBox();
    return pw.Column(
      crossAxisAlignment: pw.CrossAxisAlignment.start,
      children: [
        _tituloSeccion('Datos del Paciente', Icons.person),
        pw.SizedBox(height: 8),
        pw.Container(
          padding: const pw.EdgeInsets.all(14),
          decoration: pw.BoxDecoration(
            color: _grisClaro,
            borderRadius: pw.BorderRadius.circular(8),
            border: pw.Border.all(color: _borde),
          ),
          child: pw.Column(children: [
            pw.Row(children: [
              _campo('Nombre completo', p['nombre']    ?? '—'),
              _campo('Documento',       p['documento'] ?? '—'),
            ]),
            pw.SizedBox(height: 8),
            pw.Row(children: [
              _campo('Fecha de nacimiento', p['fecha_nac'] ?? '—'),
              _campo('Sexo biologico',      p['sexo']     ?? '—'),
            ]),
            pw.SizedBox(height: 8),
            pw.Row(children: [
              _campo('Vereda',    p['vereda']    ?? '—'),
              _campo('Municipio', p['municipio'] ?? '—'),
            ]),
            pw.SizedBox(height: 8),
            pw.Row(children: [
              _campo('Telefono',           p['telefono'] ?? '—'),
              _campo('Modulo de atencion', p['modulo']   ?? '—'),
            ]),
            if ((p['eps'] ?? '').toString().isNotEmpty) ...[
              pw.SizedBox(height: 8),
              pw.Row(children: [
                _campo('EPS / Aseguradora', p['eps'] ?? '—'),
                _campo('Departamento',      p['departamento'] ?? 'Cauca'),
              ]),
            ],
          ]),
        ),
      ],
    );
  }

  // ════════════════════════════════════════════════════════════════════════
  // SECCIÓN CONSULTAS
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _seccionConsultas(List<Map<String, dynamic>> consultas) {
    return pw.Column(
      crossAxisAlignment: pw.CrossAxisAlignment.start,
      children: [
        _tituloSeccion('Historial de Consultas (${consultas.length})', Icons.medical_services),
        pw.SizedBox(height: 8),
        if (consultas.isEmpty)
          _mensajeVacio('Sin consultas registradas.')
        else
          ...consultas.map((c) => _tarjetaConsulta(c)),
      ],
    );
  }

  static pw.Widget _tarjetaConsulta(Map<String, dynamic> c) {
    final nivel = c['nivel_riesgo'] ?? 'normal';
    final color = _colorNivel(nivel);
    final fecha = _formatFecha(c['fecha']);

    Map<String, dynamic> datos = {};
    try { datos = jsonDecode(c['datos_json'] ?? '{}'); } catch (_) {}

    final diagnostico = _limpiar(c['diagnostico'] as String? ?? '');
    final observaciones = _limpiar(c['observaciones'] as String? ?? '');

    return pw.Container(
      margin: const pw.EdgeInsets.only(bottom: 10),
      padding: const pw.EdgeInsets.all(11),
      decoration: pw.BoxDecoration(
        border: pw.Border.all(color: color, width: 0.7),
        borderRadius: pw.BorderRadius.circular(7),
        color: PdfColors.white,
      ),
      child: pw.Column(
        crossAxisAlignment: pw.CrossAxisAlignment.start,
        children: [
          // Cabecera
          pw.Row(
            mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
            children: [
              // Módulo pill
              pw.Container(
                padding: const pw.EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: pw.BoxDecoration(
                  color: color,
                  borderRadius: pw.BorderRadius.circular(20),
                ),
                child: pw.Text(
                  c['modulo'] ?? '',
                  style: pw.TextStyle(
                      fontSize: 8,
                      color: PdfColors.white,
                      fontWeight: pw.FontWeight.bold),
                ),
              ),
              pw.Text(fecha,
                  style: pw.TextStyle(fontSize: 8, color: PdfColors.grey600)),
              // Nivel pill
              pw.Container(
                padding: const pw.EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: pw.BoxDecoration(
                  color: color.shade(0.12),
                  borderRadius: pw.BorderRadius.circular(20),
                ),
                child: pw.Text(
                  nivel.toUpperCase(),
                  style: pw.TextStyle(
                      fontSize: 7,
                      color: color,
                      fontWeight: pw.FontWeight.bold),
                ),
              ),
            ],
          ),
          // Diagnóstico
          if (diagnostico.isNotEmpty) ...[
            pw.SizedBox(height: 7),
            pw.Container(
              width: double.infinity,
              padding: const pw.EdgeInsets.all(7),
              decoration: pw.BoxDecoration(
                color: color.shade(0.06),
                borderRadius: pw.BorderRadius.circular(5),
              ),
              child: pw.Text(
                diagnostico,
                style: pw.TextStyle(fontSize: 9.5, color: _texto),
              ),
            ),
          ],
          // Observaciones
          if (observaciones.isNotEmpty && observaciones != diagnostico) ...[
            pw.SizedBox(height: 5),
            pw.Text(
              observaciones,
              style: pw.TextStyle(fontSize: 8.5, color: PdfColors.grey700),
              maxLines: 4,
            ),
          ],
          // Datos clínicos
          if (datos.isNotEmpty) ...[
            pw.SizedBox(height: 7),
            pw.Container(
              padding: const pw.EdgeInsets.all(6),
              decoration: pw.BoxDecoration(
                color: _grisClaro,
                borderRadius: pw.BorderRadius.circular(5),
              ),
              child: pw.Wrap(
                spacing: 18,
                runSpacing: 3,
                children: datos.entries.take(10).map((e) => pw.RichText(
                  text: pw.TextSpan(children: [
                    pw.TextSpan(
                        text: '${e.key}: ',
                        style: pw.TextStyle(
                            fontSize: 8, color: PdfColors.grey600)),
                    pw.TextSpan(
                        text: e.value.toString(),
                        style: pw.TextStyle(
                            fontSize: 8,
                            fontWeight: pw.FontWeight.bold,
                            color: _texto)),
                  ]),
                )).toList(),
              ),
            ),
          ],
        ],
      ),
    );
  }

  // ════════════════════════════════════════════════════════════════════════
  // SECCIÓN ALERTAS SIVIGILA
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _seccionAlertas(List<Map<String, dynamic>> alertasSqlite) {
    final alertasPromotor = alertasSqlite
        .where((a) => (a['resuelta'] as int? ?? 0) == 0)
        .toList();

    return pw.Column(
      crossAxisAlignment: pw.CrossAxisAlignment.start,
      children: [
        _tituloSeccion('Alertas SIVIGILA Activas', Icons.warning),
        pw.SizedBox(height: 8),

        // Banner SIVIGILA
        pw.Container(
          padding: const pw.EdgeInsets.symmetric(horizontal: 10, vertical: 6),
          margin: const pw.EdgeInsets.only(bottom: 10),
          decoration: pw.BoxDecoration(
            color: const PdfColor.fromInt(0xFFFFF8E1),
            borderRadius: pw.BorderRadius.circular(6),
            border: pw.Border.all(color: PdfColors.orange300),
          ),
          child: pw.Row(children: [
            pw.Text(
              'Sistema de Vigilancia Epidemiologica (SIVIGILA) — Cauca, Colombia',
              style: pw.TextStyle(
                  fontSize: 9,
                  color: PdfColors.orange900,
                  fontWeight: pw.FontWeight.bold),
            ),
          ]),
        ),

        // Alertas del sistema
        pw.Text('Alertas epidemiologicas en zona:',
            style: pw.TextStyle(
                fontSize: 9.5,
                color: PdfColors.grey700,
                fontWeight: pw.FontWeight.bold)),
        pw.SizedBox(height: 5),
        ..._kAlertasActivas.map((a) => _tarjetaAlerta(
          nombre: a['nombre'],
          municipio: a['municipio'],
          nivel: a['nivel'],
          mensaje: a['mensaje'],
          casos: a['casos'],
        )),

        if (alertasPromotor.isNotEmpty) ...[
          pw.SizedBox(height: 10),
          pw.Text('Alertas registradas por el promotor:',
              style: pw.TextStyle(
                  fontSize: 9.5,
                  color: PdfColors.grey700,
                  fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 5),
          ...alertasPromotor.map((a) => _tarjetaAlerta(
            nombre: a['modulo'] ?? 'General',
            municipio: a['paciente'] ?? '',
            nivel: a['nivel'] ?? 'normal',
            mensaje: a['mensaje'] ?? '',
            casos: null,
          )),
        ],
      ],
    );
  }

  static pw.Widget _tarjetaAlerta({
    required String nombre,
    required String municipio,
    required String nivel,
    required String mensaje,
    int? casos,
  }) {
    final color = _colorNivel(nivel);
    return pw.Container(
      margin: const pw.EdgeInsets.only(bottom: 7),
      padding: const pw.EdgeInsets.all(9),
      decoration: pw.BoxDecoration(
        border: pw.Border.all(color: color, width: 0.7),
        borderRadius: pw.BorderRadius.circular(6),
      ),
      child: pw.Row(
        crossAxisAlignment: pw.CrossAxisAlignment.start,
        children: [
          pw.Container(
            padding: const pw.EdgeInsets.symmetric(horizontal: 6, vertical: 3),
            decoration: pw.BoxDecoration(
              color: color,
              borderRadius: pw.BorderRadius.circular(4),
            ),
            child: pw.Text(nivel.toUpperCase(),
                style: pw.TextStyle(
                    fontSize: 8,
                    color: PdfColors.white,
                    fontWeight: pw.FontWeight.bold)),
          ),
          pw.SizedBox(width: 9),
          pw.Expanded(
            child: pw.Column(
              crossAxisAlignment: pw.CrossAxisAlignment.start,
              children: [
                pw.Row(children: [
                  pw.Text(nombre,
                      style: pw.TextStyle(
                          fontSize: 10,
                          fontWeight: pw.FontWeight.bold,
                          color: _texto)),
                  if (municipio.isNotEmpty)
                    pw.Text('  ·  $municipio',
                        style: pw.TextStyle(
                            fontSize: 8.5, color: PdfColors.grey600)),
                  if (casos != null)
                    pw.Text('  ·  $casos casos',
                        style: pw.TextStyle(
                            fontSize: 8.5,
                            color: color,
                            fontWeight: pw.FontWeight.bold)),
                ]),
                pw.SizedBox(height: 3),
                pw.Text(mensaje,
                    style: pw.TextStyle(
                        fontSize: 8.5, color: PdfColors.grey700)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ════════════════════════════════════════════════════════════════════════
  // PIE LEGAL
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _pieLegal() {
    return pw.Container(
      padding: const pw.EdgeInsets.all(10),
      decoration: pw.BoxDecoration(
        color: _grisClaro,
        borderRadius: pw.BorderRadius.circular(6),
        border: pw.Border.all(color: _borde),
      ),
      child: pw.Column(
        crossAxisAlignment: pw.CrossAxisAlignment.start,
        children: [
          pw.Row(children: [
            pw.Image(_imgDispersalud!, width: 18, height: 18),
            pw.SizedBox(width: 6),
            pw.Text('DISPERSALUD IA — Sistema de Informacion en Salud Rural',
                style: pw.TextStyle(
                    fontSize: 9,
                    fontWeight: pw.FontWeight.bold,
                    color: _verde)),
          ]),
          pw.SizedBox(height: 5),
          pw.Text(
            'Este documento es un reporte generado automaticamente por DISPERSALUD IA '
            'para uso exclusivo del promotor/a de salud rural autorizado/a. '
            'La informacion contenida es confidencial y esta protegida por la '
            'Ley 1581 de 2012 (Habeas Data) y la Ley 1751 de 2015 (Derecho fundamental a la salud). '
            'El uso indebido de este documento puede acarrear sanciones legales.',
            style: pw.TextStyle(fontSize: 7.5, color: PdfColors.grey700),
          ),
          pw.SizedBox(height: 5),
          pw.Row(
            mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
            children: [
              pw.Text(
                'Ministerio de Salud y Proteccion Social · INS · SIVIGILA',
                style: pw.TextStyle(fontSize: 7.5, color: PdfColors.grey500),
              ),
              pw.Text(
                'Generado: ${_fechaHoy()}',
                style: pw.TextStyle(fontSize: 7.5, color: PdfColors.grey500),
              ),
            ],
          ),
        ],
      ),
    );
  }

  // ════════════════════════════════════════════════════════════════════════
  // HELPERS
  // ════════════════════════════════════════════════════════════════════════
  static pw.Widget _tituloSeccion(String titulo, IconData? icono) {
    return pw.Container(
      padding: const pw.EdgeInsets.only(bottom: 6),
      decoration: const pw.BoxDecoration(
        border: pw.Border(
          bottom: pw.BorderSide(color: _verde, width: 1.5),
        ),
      ),
      child: pw.Text(titulo,
          style: pw.TextStyle(
              fontSize: 12,
              fontWeight: pw.FontWeight.bold,
              color: _verde)),
    );
  }

  static pw.Widget _campo(String label, String valor) {
    return pw.Expanded(
      child: pw.Column(
        crossAxisAlignment: pw.CrossAxisAlignment.start,
        children: [
          pw.Text(label,
              style: pw.TextStyle(fontSize: 7.5, color: PdfColors.grey600)),
          pw.SizedBox(height: 2),
          pw.Text(valor,
              style: pw.TextStyle(
                  fontSize: 10,
                  fontWeight: pw.FontWeight.bold,
                  color: _texto)),
        ],
      ),
    );
  }

  static pw.Widget _mensajeVacio(String msg) => pw.Padding(
    padding: const pw.EdgeInsets.symmetric(vertical: 12),
    child: pw.Text(msg,
        style: pw.TextStyle(fontSize: 10, color: PdfColors.grey600)),
  );

  static String _limpiar(String texto) => texto
      .replaceAll('⚠️', '[ALERTA]')
      .replaceAll('🩸', '[SANGRE]')
      .replaceAll('📋', '[NOTA]')
      .replaceAll('✅', '[OK]')
      .replaceAll('🚨', '[URGENTE]')
      .replaceAll('🌡️', '[FIEBRE]')
      .replaceAll('🧠', '[MENTAL]')
      .replaceAll('🚭', '[TABACO]')
      .replaceAll('⚖️', '[PESO]')
      .replaceAll('🫀', '[CORAZON]')
      .replaceAll('💉', '[VACUNA]')
      .replaceAll('🧒', '[NINO]')
      .replaceAll('👁️', '[VISION]')
      .replaceAll('🦷', '[DIENTE]')
      .replaceAll('😮', '[OXIGENO]')
      .replaceAll('🧓', '[ADULTO]')
      .replaceAll('🌿', '[PLANTA]')
      .replaceAll('🤰', '[GESTANTE]')
      .replaceAll(RegExp(r'[^ -~À-ɏЀ-ӿ\[\]]'), '')
      .trim();

  static PdfColor _colorNivel(String nivel) {
    switch (nivel.toLowerCase()) {
      case 'urgente': case 'rojo':    return PdfColors.red700;
      case 'alerta':  case 'naranja':
      case 'alto':                    return PdfColors.orange700;
      case 'bajo':                    return const PdfColor.fromInt(0xFF1D9E75);
      default:                        return const PdfColor.fromInt(0xFF1D9E75);
    }
  }

  static String _formatFecha(String? iso) {
    if (iso == null || iso.isEmpty) return '—';
    try {
      final dt = DateTime.parse(iso).toLocal();
      return '${dt.day.toString().padLeft(2,'0')}/${dt.month.toString().padLeft(2,'0')}/${dt.year}  ${dt.hour.toString().padLeft(2,'0')}:${dt.minute.toString().padLeft(2,'0')}';
    } catch (_) { return iso; }
  }

  static String _fechaHoy() {
    final dt = DateTime.now();
    return '${dt.day.toString().padLeft(2,'0')}/${dt.month.toString().padLeft(2,'0')}/${dt.year}';
  }
}